SELECT finalize(to_aggregate_state({'precision': 10, 'registers': list_resize([]::UTINYINT[], 1024, 56)}, 'approx_count_distinct', ['BIGINT']));
SELECT finalize(to_aggregate_state(s::STRUCT(precision UTINYINT, registers UTINYINT[]),
                                  'approx_count_distinct', ['ANY'])),
       finalize(combine(s, to_aggregate_state(s::STRUCT(precision UTINYINT, registers UTINYINT[]),
                                            'approx_count_distinct', ['ANY']))) = finalize(s),
       typeof(s) = 'AGGREGATE_STATE' AND typeof(finalize(s)) = 'BIGINT'
FROM (SELECT approx_count_distinct(v) EXPORT_STATE s FROM (VALUES (1::BIGINT),(1),(NULL),(2)) input(v));
SELECT finalize(to_aggregate_state({'precision': 10, 'registers': list_resize([]::UTINYINT[], 1024, 0)},
                                  'approx_count_distinct', ['ANY']));
SELECT finalize(combine_aggr(s)) FROM (
    SELECT approx_count_distinct(v) EXPORT_STATE s FROM (VALUES (1::BIGINT),(NULL)) input(v)
    UNION ALL
    SELECT approx_count_distinct(v) EXPORT_STATE s FROM (VALUES ('a'),(NULL)) input(v)
) input;
SELECT finalize(to_aggregate_state({'precision': 10, 'registers': [0, 0, 0]::UTINYINT[]},
                                  'approx_count_distinct', ['ANY']));
SELECT g, finalize(s),
       finalize(to_aggregate_state(s::STRUCT(precision UTINYINT, registers UTINYINT[]),
                                  'approx_count_distinct', ['ANY']))
FROM (
    SELECT g, approx_count_distinct(v) EXPORT_STATE s
    FROM (VALUES (0,1::BIGINT),(0,1),(0,NULL),(1,NULL),(2,2)) input(g,v)
    GROUP BY g
) states;

